154	export async function postReviewComments(
155	  token: string,
156	  context: PullRequestContext,
157	  comments: Comment[],
158	): Promise<void> {
159	  if (comments.length === 0) {
160	    core.info('No comments to post');
161	    return;
162	  }
163	
164	  const octokit = new Octokit({ auth: token });
165	
166	  // Fetch PR diff to validate line numbers
167	  const validRanges = await getPRDiffRanges(octokit, context);
168	
169	  // Process comments: clamp line numbers and handle invalid ones
170	  const processedComments: Comment[] = [];
171	  const invalidLineComments: Comment[] = [];
172	
173	  for (const comment of comments) {
174	    if (!comment.file || comment.line == null) {
175	      // Already a general comment
176	      processedComments.push(comment);
177	      continue;
178	    }
179	
180	    const clamped = clampCommentToValidRange(comment, validRanges);
181	    if (clamped) {
182	      processedComments.push(clamped);
183	    } else {
184	      // File not in diff - convert to general comment
185	      core.warning(
186	        `Comment on ${comment.file}:${comment.line} could not be placed in diff - converting to general comment`,
187	      );
188	      invalidLineComments.push(comment);
189	    }
190	  }
191	
192	  // Separate line-specific comments from general PR comments
193	  const lineComments = processedComments.filter((c) => c.file && c.finding);
194	  const generalComments = processedComments.filter((c) => !c.file && c.finding);
195	
196	  // Post line-specific review comments
197	  if (lineComments.length > 0) {
198	    core.info(`Posting ${lineComments.length} line-specific review comments...`);
199	
200	    try {
201	      await octokit.pulls.createReview({
202	        owner: context.owner,
203	        repo: context.repo,
204	        pull_number: context.number,
205	        event: 'COMMENT',
206	        comments: lineComments.map((c) => {
207	          // Combine finding and fix into comment body
208	          let body = c.finding;
209	          if (c.fix) {
210	            body += `\n\n<details>\n<summary>Suggested Fix</summary>\n\n${c.fix}\n</details>`;
211	          }
212	
213	          return {
214	            path: c.file!,
215	            line: c.line || undefined,
216	            start_line: c.startLine && c.line && c.startLine < c.line ? c.startLine : undefined,
217	            side: 'RIGHT' as const,
218	            start_side:
219	              c.startLine && c.line && c.startLine < c.line ? ('RIGHT' as const) : undefined,
220	            body,
221	          };
222	        }),
223	      });
224	
225	      core.info(`✅ Posted ${lineComments.length} line comments successfully`);
226	    } catch (error) {
