35	/**
36	 * Extract valid line ranges from a unified diff.
37	 *
38	 * Parses a multi-file unified diff (like what GitHub returns for a PR)
39	 * and extracts the valid line ranges for each file. These ranges represent
40	 * lines that can receive PR review comments.
41	 *
42	 * @param unifiedDiff - Full unified diff string (may contain multiple files)
43	 * @returns Map of file paths to their valid line ranges in the NEW file
44	 *
45	 * @example
46	 * ```typescript
47	 * const diff = `diff --git a/src/foo.ts b/src/foo.ts
48	 * --- a/src/foo.ts
49	 * +++ b/src/foo.ts
50	 * @@ -10,7 +10,8 @@
51	 *    context
52	 * -  removed
53	 * +  added
54	 *    context`;
55	 *
56	 * const ranges = extractValidLineRanges(diff);
57	 * // Map { 'src/foo.ts' => [{ start: 10, end: 17 }] }
58	 * ```
59	 */
60	export function extractValidLineRanges(unifiedDiff: string): FileLineRanges {
61	  const ranges: FileLineRanges = new Map();
62	
63	  if (!unifiedDiff || unifiedDiff.trim() === '') {
64	    return ranges;
65	  }
66	
67	  const lines = unifiedDiff.split('\n');
68	  let currentFile: string | null = null;
69	  let currentRanges: LineRange[] = [];
70	  let currentNewLine = 0;
71	  let hunkStartLine = 0;
72	
73	  for (const line of lines) {
74	    // Match file header: diff --git a/path b/path
75	    // or +++ b/path (for new file path)
76	    const fileMatch = line.match(/^\+\+\+ b\/(.+)$/);
77	    if (fileMatch) {
78	      // Close current hunk if we have one (before switching files)
79	      if (currentFile && hunkStartLine > 0 && currentNewLine > hunkStartLine) {
80	        currentRanges.push({
81	          start: hunkStartLine,
82	          end: currentNewLine - 1,
83	        });
84	      }
85	
86	      // Save previous file's ranges
87	      if (currentFile && currentRanges.length > 0) {
88	        ranges.set(currentFile, currentRanges);
89	      }
90	
91	      currentFile = fileMatch[1];
92	      currentRanges = [];
93	      currentNewLine = 0;
94	      hunkStartLine = 0;
95	      continue;
96	    }
97	
98	    // Match hunk header: @@ -old,count +new,count @@
99	    const hunkHeader = parseHunkHeader(line);
100	    if (hunkHeader && currentFile) {
101	      // Save the previous hunk's range if we have one
102	      if (hunkStartLine > 0 && currentNewLine > hunkStartLine) {
103	        currentRanges.push({
104	          start: hunkStartLine,
105	          end: currentNewLine - 1,
106	        });
107	      }
108	
109	      // Start tracking new hunk
110	      hunkStartLine = hunkHeader.newStart;
111	      currentNewLine = hunkHeader.newStart;
112	
113	      // For hunks with 0 lines in new file (pure deletion), don't start a range
114	      if (hunkHeader.newCount === 0) {
115	        hunkStartLine = 0;
116	      }
117	      continue;
118	    }
119	
120	    // Track line numbers within hunks
121	    if (currentFile && hunkStartLine > 0) {
122	      if (line.startsWith('-')) {
123	        // Removed line - doesn't exist in new file
124	        continue;
125	      } else if (line.startsWith('+') || line.startsWith(' ') || line === '') {
126	        // Added line, context line, or empty line within hunk
127	        currentNewLine++;
128	      } else if (line.startsWith('\\')) {
129	        // Special marker like "\ No newline at end of file" - skip
130	        continue;
131	      }
132	    }
133	  }
134	
135	  // Save the last file's ranges
136	  if (currentFile) {
137	    if (hunkStartLine > 0 && currentNewLine > hunkStartLine) {
138	      currentRanges.push({
139	        start: hunkStartLine,
140	        end: currentNewLine - 1,
141	      });
142	    }
143	    if (currentRanges.length > 0) {
144	      ranges.set(currentFile, currentRanges);
145	    }
146	  }
147	
148	  return ranges;
149	}
